import { useCallback, useEffect, useRef, useState } from 'react';
import { api } from './format.js';

const GREETING = 'What would you like to stress-test? I’ll ask for an estimate if the account data doesn’t identify a cost.';
const REPLACED = 'This interpretation has been replaced. Use the latest scenario.';
const DEFAULT_ACCOUNT = 20134;

const recentKey = id => 'runway:recentQueries:' + id;
function readRecent(id) {
  try {
    const saved = JSON.parse(sessionStorage.getItem(recentKey(id)) || '[]');
    return Array.isArray(saved) ? saved.filter(q => typeof q === 'string' && q.trim() && q.length <= 500).slice(0, 2) : [];
  } catch { return []; }
}

// All app state and the API workflow: load an account, interpret a shock, clarify, apply, re-plan.
export function useCushion() {
  const [health, setHealth] = useState('Connecting…');
  const [accountIds, setAccountIds] = useState([]);
  const [account, setAccount] = useState(DEFAULT_ACCOUNT);
  const [baseline, setBaseline] = useState(null);
  const [plan, setPlan] = useState(null);
  const [planVersion, setPlanVersion] = useState(0);
  const [planning, setPlanning] = useState({});
  const [explanation, setExplanation] = useState(null);
  const [messages, setMessages] = useState([]);
  const [recentQueries, setRecentQueries] = useState([]);
  const [busy, setBusyState] = useState(false);
  const [pageError, setPageError] = useState('');
  const [planningError, setPlanningError] = useState('');
  const [manualOpen, setManualOpen] = useState(false);

  // Values read synchronously inside async handlers (React state would be stale there).
  const s = useRef({
    account: DEFAULT_ACCOUNT, busy: false, revision: 0, planToken: 0, appliedShock: null, planning: {},
    amounts: {}, duration: null, incomePct: null, overlap: false, recent: [],
  }).current;
  const nextId = useRef(0);

  const setBusy = on => { s.busy = on; setBusyState(on); };
  const resetClarifications = () => { s.amounts = {}; s.duration = null; s.incomePct = null; s.overlap = false; };

  const addMessage = msg => setMessages(m => [...m, { id: ++nextId.current, ...msg }]);
  const say = (text, extra = {}) => addMessage({ kind: 'text', text, ...extra });
  const markDone = id => setMessages(m => m.map(x => (x.id === id ? { ...x, done: true } : x)));
  const interpretation = result => addMessage({ kind: 'interp', result, revision: s.revision, done: false });

  function showPlan(p) {
    const token = ++s.planToken;
    setPlan(p);
    setPlanVersion(v => v + 1);
    setExplanation({ loading: true });
    api('/api/explain', p)
      .then(t => { if (token === s.planToken) setExplanation({ data: t }); })
      .catch(e => { if (token === s.planToken) setExplanation({ error: e.message }); });
  }

  const loadAccount = useCallback(async id => {
    setBusy(true);
    setPageError('');
    try {
      const b = await api(`/api/accounts/${id}/baseline`);
      s.account = id;
      s.recent = readRecent(id);
      s.appliedShock = null;
      s.planning = {};
      s.revision++;
      s.planToken++;
      resetClarifications();
      setAccount(id);
      setRecentQueries(s.recent);
      setBaseline(b);
      setPlan(null);
      setPlanning({});
      setExplanation(null);
      setPlanningError('');
      setMessages([{ id: ++nextId.current, kind: 'text', text: GREETING }]);
    } catch (e) {
      setPageError(e.message);
    } finally {
      setBusy(false);
    }
  }, []); // eslint-disable-line react-hooks/exhaustive-deps

  useEffect(() => {
    (async () => {
      try {
        const h = await api('/api/health');
        setHealth(h.gemini_enabled ? 'Gemini configured · local data' : 'Manual mode · Gemini disabled');
        const ids = await api('/api/accounts');
        setAccountIds(ids.account_ids);
      } catch {
        setHealth('Connection unavailable');
      }
      await loadAccount(DEFAULT_ACCOUNT);
    })();
  }, [loadAccount]);

  function rememberQuery(text) {
    s.recent = [text, ...s.recent].slice(0, 2);
    try { sessionStorage.setItem(recentKey(s.account), JSON.stringify(s.recent)); } catch { /* storage unavailable */ }
    setRecentQueries(s.recent);
  }

  // morphFrom: the text box's on-screen rectangle, so the sent message can animate out of it.
  async function sendQuery(text, morphFrom) {
    if (s.busy) return;
    s.revision++;
    rememberQuery(text);
    say(text, { user: true, morphFrom });
    resetClarifications();
    setBusy(true);
    try {
      const r = await api('/api/parse-shock', { account_id: s.account, text });
      if (['ok', 'needs_input'].includes(r.status)) interpretation(r);
      else {
        say(r.message || 'No usable change was found. Try a more specific scenario.');
        if (r.status === 'error') setManualOpen(true);
      }
    } catch (e) {
      say(e.message);
    } finally {
      setBusy(false);
    }
  }

  function submitManual(f) {
    if (s.busy) return;
    const duration = Number(f.get('duration'));
    const change = Number(f.get('recurring'));
    const oneoff = Number(f.get('oneoff'));
    s.revision++;
    say('Manual scenario entered. Please review the amounts before applying.', { user: true });
    interpretation({
      status: 'ok',
      interpretation: 'All changes are held constant during the selected assessment window.',
      assumptions: change ? ['Recurring amount is a user-supplied change, already net of the existing category cost.'] : [],
      shock: {
        income_multiplier: Number(f.get('income')) / 100,
        income_duration_months: duration,
        scenario_duration_months: duration,
        household_bills_pct_change: Number(f.get('bills')),
        one_off_costs: oneoff ? [{ label: 'Immediate expense', amount_dollars: oneoff }] : [],
        recurring_costs: change ? [{ label: f.get('label'), monthly_change: change, source: 'user_estimate' }] : [],
      },
    });
  }

  async function clarify(msg, fd) {
    if (s.busy) return;
    if (msg.revision !== s.revision) { say(REPLACED); return; }
    for (const [k, v] of fd) {
      if (k.startsWith('amount_')) s.amounts[k.slice(7)] = Number(v);
      if (k === 'duration') s.duration = Number(v);
      if (k === 'incomePct') s.incomePct = Number(v);
      if (k === 'overlap') s.overlap = true;
    }
    setBusy(true);
    try {
      const r = await api('/api/resolve-shock', {
        account_id: s.account, draft: msg.result.draft, category_amounts: s.amounts, duration_months: s.duration,
        income_replacement_pct: s.incomePct, overlap_acknowledged: s.overlap,
      });
      markDone(msg.id);
      interpretation(r);
    } catch (e) {
      say(e.message);
    } finally {
      setBusy(false);
    }
  }

  async function applyScenario(msg) {
    if (s.busy) return;
    if (msg.revision !== s.revision) { say(REPLACED); return; }
    const shock = msg.result.shock;
    const choices = {
      target_months: s.planning.target_months ?? 3,
      deadline_months: s.planning.deadline_months ?? 12,
      monthly_contribution: s.planning.monthly_contribution ?? null,
    };
    setBusy(true);
    try {
      const p = await api('/api/plan', { account_id: s.account, shock, planning: choices });
      s.planning = choices;
      s.appliedShock = shock;
      setPlanning(choices);
      showPlan(p);
      markDone(msg.id);
      say('Scenario applied. The comparison and funding plan are ready.');
    } catch (e) {
      say(e.message);
    } finally {
      setBusy(false);
    }
  }

  async function recalculatePlan(settings) {
    if (s.busy || !s.appliedShock) return;
    setPlanningError('');
    setBusy(true);
    try {
      const p = await api('/api/plan', { account_id: s.account, shock: s.appliedShock, planning: settings });
      s.planning = settings;
      setPlanning(settings);
      showPlan(p);
    } catch (e) {
      setPlanningError(e.message);
    } finally {
      setBusy(false);
    }
  }

  return {
    health, accountIds, account, baseline, plan, planVersion, planning, explanation, messages, recentQueries,
    busy, pageError, planningError, manualOpen, setManualOpen,
    loadAccount, sendQuery, submitManual, clarify, applyScenario, recalculatePlan,
  };
}

import { baselineRunway, cash, runway } from '../format.js';
import ChatPanel from './ChatPanel.jsx';
import ResultsPanel from './ResultsPanel.jsx';

function Metrics({ baseline: b, plan }) {
  if (!b) return <div id="metrics" className="metrics" />;
  const base = plan?.baseline || baselineRunway(b);
  const cards = [
    ['Monthly inflows', cash(b.income), 'Median recorded money in'],
    ['Monthly spending', cash(b.spending), 'Median recorded money out'],
    ['Household bills', cash(b.household_bills), 'Recorded category, not rent alone'],
    ['Fixed costs', cash(b.fixed_costs), 'Median of monthly bills + insurance + loans'],
    ['Savings buffer', cash(b.buffer), 'Mean balance over last six months'],
    ['Baseline runway', runway(base), base.runway_capped ? 'Capped at 120 months' : 'Under typical conditions'],
  ];
  return (
    <div id="metrics" className="metrics">
      {cards.map(([label, value, note], i) => (
        <div key={label} className={'metric' + (i === 4 ? ' highlight' : '')}>
          <label>{label}</label><strong>{value}</strong><small>{note}</small>
        </div>
      ))}
    </div>
  );
}

export default function Dashboard({ hidden, view, show, isAdmin, c, accountInput, setAccountInput }) {
  const b = c.baseline;
  const planEmpty = view === 'plan' && !c.plan?.action_plan;
  const meta = b ? `${b.months_of_history} observed months · Active loan payment ${cash(b.loan_payment)}/month` : 'Loading account…';

  function submitAccount(e) {
    e.preventDefault();
    if (isAdmin && !c.busy) c.loadAccount(Number(accountInput));
  }

  return (
    <main id="dashboard" hidden={hidden}>
      <section className="intro">
        <div>
          <p className="eyebrow">YOUR FINANCIAL WHAT-IF LAB</p>
          <h1>Your money,<br />a little clearer.</h1>
          <p className="sub">Explore an account. Apply a shock. Find the buffer you need.</p>
        </div>
        {isAdmin ? (
          <form id="account-form" className="account-box" onSubmit={submitAccount}>
            <label htmlFor="account-id">ACCOUNT</label>
            <div className="account-input">
              <input id="account-id" type="number" min="1" list="accounts" required aria-label="Account ID"
                value={accountInput} onChange={e => setAccountInput(e.target.value)} disabled={c.busy} />
              <datalist id="accounts">{c.accountIds.map(id => <option key={id} value={id} />)}</datalist>
              <button type="submit" disabled={c.busy}>Load account ↗</button>
            </div>
            <small id="account-meta">{meta}</small>
          </form>
        ) : (
          <div className="account-box">
            <label>ACCOUNT</label>
            <strong className="account-current">Account {c.account}</strong>
            <small id="account-meta">{meta}</small>
          </div>
        )}
      </section>

      <div id="page-error" className="notice error" role="alert" hidden={!c.pageError}>{c.pageError}</div>

      <section id="customer-snapshot" aria-labelledby="snapshot-title">
        <div className="section-title">
          <h2 id="snapshot-title">Your starting point</h2>
          <span>Typical monthly values · CAD</span>
        </div>
        <Metrics baseline={b} plan={c.plan} />
      </section>

      <div className="workspace" hidden={planEmpty}>
        <ChatPanel c={c} />
        <ResultsPanel c={c} />
      </div>

      <div id="plan-empty" className="empty" hidden={!planEmpty}>
        <h2>Build a plan from your own numbers.</h2>
        <p>Apply a scenario in Stress Test to calculate your goal and backup plans.</p>
        <button type="button" onClick={() => show('stress')}>Create a stress test ↗</button>
      </div>

      <footer>
        <span>CUSHION / SHERIDAN DATATHON 2026</span>
        <span>Scenario analysis using anonymized account data. Recorded inflows are not verified salary.</span>
        <a href="/docs">API docs ↗</a>
      </footer>
    </main>
  );
}

"""FastAPI app. Run: uvicorn app.main:app --reload  (from backend/)"""
from __future__ import annotations

from dataclasses import asdict
from typing import Any

from fastapi import Depends, FastAPI, HTTPException
from fastapi.middleware.cors import CORSMiddleware
from pathlib import Path

from fastapi.responses import HTMLResponse, JSONResponse
from fastapi.staticfiles import StaticFiles
from pydantic import BaseModel, Field, model_validator
from sqlalchemy.orm import Session

from .ai import config, explainer, shock_parser
from .finance import engine
from .db.config import BACKUP_SQL, backup_mode, build_url
from .db import (AccountNotFound, DatabaseUnavailable, NoHistory, get_session, load_config, services,
                 session_scope)
from .ai.shock_parser import LIMITS
from .finance.planning import PlanningOptions

app = FastAPI(title="Tangerine resilience engine")
app.add_middleware(
    CORSMiddleware,
    allow_origins=["http://localhost:3000", "http://localhost:5173"],
    allow_methods=["*"], allow_headers=["*"],
)
explainer.load_cache()


class OneOffModel(BaseModel):
    label: str = "one-off cost"
    amount_dollars: float | None = Field(None, ge=0, le=shock_parser.MAX_ONE_OFF_DOLLARS)
    multiple_of_monthly_spending: float | None = Field(None, ge=LIMITS["multiple_of_monthly_spending"][0],
                                                       le=LIMITS["multiple_of_monthly_spending"][1])

    @model_validator(mode="after")
    def exactly_one_size(self):
        if (self.amount_dollars is None) == (self.multiple_of_monthly_spending is None):
            raise ValueError("Provide exactly one one-off size: dollars or a spending multiple")
        return self


class RecurringModel(BaseModel):
    label: str = Field(min_length=1, max_length=100)
    monthly_change: float = Field(ge=-1_000_000, le=1_000_000, allow_inf_nan=False)
    source: str = "user_estimate"


class ShockModel(BaseModel):
    """Slider values. Null = unchanged. Ranges enforced here so nothing out of range reaches the engine."""
    income_multiplier: float | None = Field(None, ge=LIMITS["income_multiplier"][0], le=LIMITS["income_multiplier"][1])
    income_duration_months: int | None = Field(None, ge=LIMITS["income_duration_months"][0],
                                               le=LIMITS["income_duration_months"][1])
    household_bills_pct_change: float | None = Field(None, ge=-50, le=200)
    spending_pct_change: float | None = Field(None, ge=-50, le=200)
    one_off_costs: list[OneOffModel] = []

    recurring_costs: list[RecurringModel] = Field(default_factory=list)
    scenario_duration_months: int | None = Field(None, ge=1, le=60)
    overlap_acknowledged: bool = False

    def to_engine(self) -> engine.Shock:
        return engine.Shock(
            self.income_multiplier, self.income_duration_months, self.household_bills_pct_change,
            self.spending_pct_change,
            [engine.OneOffCost(c.label, c.amount_dollars, c.multiple_of_monthly_spending)
             for c in self.one_off_costs],
            recurring_costs=[engine.RecurringCost(c.label, c.monthly_change, c.source) for c in self.recurring_costs],
            scenario_duration_months=self.scenario_duration_months,
            overlap_acknowledged=self.overlap_acknowledged)


class PlanningModel(BaseModel):
    target_months: int = Field(3, ge=1, le=12)
    deadline_months: int = Field(12, ge=1, le=120)
    monthly_contribution: float | None = Field(None, gt=0, le=1_000_000, allow_inf_nan=False)
    confirmed_monthly_cut: float = Field(0, ge=0, le=1_000_000, allow_inf_nan=False)
    confirmed_extra_income: float = Field(0, ge=0, le=1_000_000, allow_inf_nan=False)
    confirmed_upfront_funds: float = Field(0, ge=0, le=1_000_000, allow_inf_nan=False)


class PlanRequest(BaseModel):
    account_id: int
    shock: ShockModel = ShockModel()
    planning: PlanningModel = Field(default_factory=PlanningModel)


class ParseRequest(BaseModel):
    text: str
    account_id: int | None = None      # only used to show dollar amounts; never sent to Gemini


@app.exception_handler(AccountNotFound)
def _not_found(_, e: AccountNotFound):
    return JSONResponse({"detail": str(e)}, status_code=404)


@app.exception_handler(NoHistory)
def _no_history(_, e: NoHistory):
    return JSONResponse({"detail": str(e)}, status_code=422)


@app.exception_handler(DatabaseUnavailable)
def _db_down(_, e: DatabaseUnavailable):
    return JSONResponse({"detail": str(e)}, status_code=503)


def _database_status() -> str:
    if backup_mode():
        return "backup" if BACKUP_SQL.exists() else "backup_missing"
    return "configured" if _database_configured() else "not_configured"


def _database_configured() -> bool:
    try:
        build_url(load_config())      # present and well-formed (does not connect)
        return True
    except DatabaseUnavailable:
        return False


def _without_id(obj) -> dict[str, Any]:
    return {k: v for k, v in asdict(obj).items() if k != "account_id"}


@app.get("/api/health")
def health() -> dict[str, Any]:
    return {"ok": True, "gemini_enabled": not config.gemini_disabled(),
            "gemini_model": config.gemini_model(),
            "gemini_timeout_seconds": config.GEMINI_TIMEOUT_S,
            "database": _database_status()}


@app.get("/api/accounts/{account_id}/baseline")
def baseline(account_id: int, session: Session = Depends(get_session)) -> dict[str, Any]:
    snap = services.get_account_snapshot(session, account_id)
    return {"account_id": account_id, **_without_id(snap.baseline),
            "loan_payment": snap.loan_payment, "flexible_spending": _without_id(snap.flexible)}


@app.post("/api/plan")
def plan(req: PlanRequest, session: Session = Depends(get_session)) -> dict[str, Any]:
    """Numbers only (fast). The UI shows these first, then calls /api/explain."""
    try:
        return engine.plan_for_account(session, req.account_id, req.shock.to_engine(),
                                       PlanningOptions(**req.planning.model_dump()))
    except ValueError as e:
        raise HTTPException(422, str(e))


@app.post("/api/explain")
def explain(plan_json: dict[str, Any]) -> dict[str, str]:
    """Body: the plan JSON returned by /api/plan. Always returns text (template if Gemini fails)."""
    if "baseline" not in plan_json or "after_shock" not in plan_json:
        raise HTTPException(422, "body must be a plan from /api/plan")
    return explainer.explain_plan({k: v for k, v in plan_json.items() if k != "action_plan"})


@app.post("/api/parse-shock")
def parse_shock(req: ParseRequest) -> dict[str, Any]:
    base = None
    if req.account_id is not None:
        # Session opened only when needed, so parsing still works with no database configured.
        with session_scope() as session:
            base = _without_id(services.get_account_baseline(session, req.account_id))
    return shock_parser.parse_shock(req.text, base)


class ResolveRequest(BaseModel):
    account_id: int
    draft: shock_parser.ParsedShockSchema
    category_amounts: dict[str, float] = Field(default_factory=dict)
    duration_months: int | None = Field(None, ge=1, le=60)
    income_replacement_pct: float | None = Field(None, ge=0, le=150, allow_inf_nan=False)
    overlap_acknowledged: bool = False


@app.post("/api/resolve-shock")
def resolve_shock(req: ResolveRequest, session: Session = Depends(get_session)):
    base = _without_id(services.get_account_baseline(session, req.account_id))
    try:
        return shock_parser.resolve_draft(req.draft, base, req.category_amounts,
                                          req.duration_months, req.overlap_acknowledged, req.income_replacement_pct)
    except ValueError as e:
        raise HTTPException(422, str(e))


@app.get("/api/accounts")
def accounts(session: Session = Depends(get_session)):
    return {"account_ids": sorted(services.get_all_baselines(session))}


# Built React app (npm run build -> frontend/dist). Mounted last so every /api route above wins.
FRONTEND_DIST = Path(__file__).resolve().parents[2] / "frontend" / "dist"
if (FRONTEND_DIST / "index.html").exists():
    app.mount("/", StaticFiles(directory=FRONTEND_DIST, html=True), name="frontend")
else:
    @app.get("/", include_in_schema=False)
    def frontend_not_built():
        return HTMLResponse("<p>Frontend not built. Run <code>npm run build</code> from the repository root, "
                            "or <code>npm start</code> and open http://localhost:5173.</p>")

