33	  // Values read synchronously inside async handlers (React state would be stale there).
34	  const s = useRef({
35	    account: DEFAULT_ACCOUNT, busy: false, revision: 0, planToken: 0, appliedShock: null, planning: {},
36	    amounts: {}, duration: null, incomePct: null, overlap: false, recent: [],
37	  }).current;
38	  const nextId = useRef(0);
39	
40	  const setBusy = on => { s.busy = on; setBusyState(on); };
41	  const resetClarifications = () => { s.amounts = {}; s.duration = null; s.incomePct = null; s.overlap = false; };
42	
43	  const addMessage = msg => setMessages(m => [...m, { id: ++nextId.current, ...msg }]);
44	  const say = (text, extra = {}) => addMessage({ kind: 'text', text, ...extra });
45	  const markDone = id => setMessages(m => m.map(x => (x.id === id ? { ...x, done: true } : x)));
46	  const interpretation = result => addMessage({ kind: 'interp', result, revision: s.revision, done: false });
47	
48	  function showPlan(p) {
49	    const token = ++s.planToken;
50	    setPlan(p);
51	    setPlanVersion(v => v + 1);
52	    setExplanation({ loading: true });
53	    api('/api/explain', p)
54	      .then(t => { if (token === s.planToken) setExplanation({ data: t }); })
55	      .catch(e => { if (token === s.planToken) setExplanation({ error: e.message }); });
56	  }
57	
58	  const loadAccount = useCallback(async id => {
59	    setBusy(true);
60	    setPageError('');
61	    try {
62	      const b = await api(`/api/accounts/${id}/baseline`);
63	      s.account = id;
64	      s.recent = readRecent(id);
65	      s.appliedShock = null;
66	      s.planning = {};
67	      s.revision++;
68	      s.planToken++;
69	      resetClarifications();
70	      setAccount(id);
71	      setRecentQueries(s.recent);
72	      setBaseline(b);
73	      setPlan(null);
74	      setPlanning({});
75	      setExplanation(null);
76	      setPlanningError('');
77	      setMessages([{ id: ++nextId.current, kind: 'text', text: GREETING }]);
78	    } catch (e) {
79	      setPageError(e.message);
80	    } finally {
81	      setBusy(false);
82	    }
83	  }, []); // eslint-disable-line react-hooks/exhaustive-deps
84	
85	  useEffect(() => {
86	    (async () => {
87	      try {
88	        const h = await api('/api/health');
89	        setHealth(h.gemini_enabled ? 'Gemini configured · local data' : 'Manual mode · Gemini disabled');
90	        const ids = await api('/api/accounts');
91	        setAccountIds(ids.account_ids);
92	      } catch {
93	        setHealth('Connection unavailable');
94	      }
95	      await loadAccount(DEFAULT_ACCOUNT);
96	    })();
97	  }, [loadAccount]);
98	
99	  function rememberQuery(text) {
100	    s.recent = [text, ...s.recent].slice(0, 2);
101	    try { sessionStorage.setItem(recentKey(s.account), JSON.stringify(s.recent)); } catch { /* storage unavailable */ }
102	    setRecentQueries(s.recent);
103	  }
104	
105	  // morphFrom: the text box's on-screen rectangle, so the sent message can animate out of it.
106	  async function sendQuery(text, morphFrom) {
107	    if (s.busy) return;
108	    s.revision++;
109	    rememberQuery(text);
110	    say(text, { user: true, morphFrom });
111	    resetClarifications();
112	    setBusy(true);
113	    try {
114	      const r = await api('/api/parse-shock', { account_id: s.account, text });
115	      if (['ok', 'needs_input'].includes(r.status)) interpretation(r);
116	      else {
117	        say(r.message || 'No usable change was found. Try a more specific scenario.');
118	        if (r.status === 'error') setManualOpen(true);
119	      }
120	    } catch (e) {
121	      say(e.message);
122	    } finally {
123	      setBusy(false);
124	    }
125	  }
126	
127	  function submitManual(f) {
128	    if (s.busy) return;
129	    const duration = Number(f.get('duration'));
130	    const change = Number(f.get('recurring'));
131	    const oneoff = Number(f.get('oneoff'));
132	    s.revision++;
133	    say('Manual scenario entered. Please review the amounts before applying.', { user: true });
134	    interpretation({
135	      status: 'ok',
136	      interpretation: 'All changes are held constant during the selected assessment window.',
137	      assumptions: change ? ['Recurring amount is a user-supplied change, already net of the existing category cost.'] : [],
138	      shock: {
139	        income_multiplier: Number(f.get('income')) / 100,
140	        income_duration_months: duration,
141	        scenario_duration_months: duration,
142	        household_bills_pct_change: Number(f.get('bills')),
143	        one_off_costs: oneoff ? [{ label: 'Immediate expense', amount_dollars: oneoff }] : [],
144	        recurring_costs: change ? [{ label: f.get('label'), monthly_change: change, source: 'user_estimate' }] : [],
145	      },
146	    });
147	  }
148	
149	  async function clarify(msg, fd) {
150	    if (s.busy) return;
151	    if (msg.revision !== s.revision) { say(REPLACED); return; }
152	    for (const [k, v] of fd) {
153	      if (k.startsWith('amount_')) s.amounts[k.slice(7)] = Number(v);
154	      if (k === 'duration') s.duration = Number(v);
155	      if (k === 'incomePct') s.incomePct = Number(v);
156	      if (k === 'overlap') s.overlap = true;
157	    }
158	    setBusy(true);
159	    try {
160	      const r = await api('/api/resolve-shock', {
161	        account_id: s.account, draft: msg.result.draft, category_amounts: s.amounts, duration_months: s.duration,
162	        income_replacement_pct: s.incomePct, overlap_acknowledged: s.overlap,
163	      });
164	      markDone(msg.id);
165	      interpretation(r);
166	    } catch (e) {
167	      say(e.message);
168	    } finally {
169	      setBusy(false);
170	    }
171	  }
172	
173	  async function applyScenario(msg) {
174	    if (s.busy) return;
175	    if (msg.revision !== s.revision) { say(REPLACED); return; }
176	    const shock = msg.result.shock;
177	    const choices = {
178	      target_months: s.planning.target_months ?? 3,
179	      deadline_months: s.planning.deadline_months ?? 12,
180	      monthly_contribution: s.planning.monthly_contribution ?? null,
181	    };
182	    setBusy(true);
183	    try {
184	      const p = await api('/api/plan', { account_id: s.account, shock, planning: choices });
185	      s.planning = choices;
186	      s.appliedShock = shock;
187	      setPlanning(choices);
188	      showPlan(p);
189	      markDone(msg.id);
190	      say('Scenario applied. The comparison and funding plan are ready.');
191	    } catch (e) {
192	      say(e.message);
193	    } finally {
194	      setBusy(false);
195	    }
196	  }
197	
198	  async function recalculatePlan(settings) {
199	    if (s.busy || !s.appliedShock) return;
200	    setPlanningError('');
201	    setBusy(true);
202	    try {
203	      const p = await api('/api/plan', { account_id: s.account, shock: s.appliedShock, planning: settings });
204	      s.planning = settings;
205	      setPlanning(settings);
206	      showPlan(p);
207	    } catch (e) {
208	      setPlanningError(e.message);
209	    } finally {
210	      setBusy(false);
211	    }
212	  }
213	
214	  return {
215	    health, accountIds, account, baseline, plan, planVersion, planning, explanation, messages, recentQueries,
216	    busy, pageError, planningError, manualOpen, setManualOpen,
217	    loadAccount, sendQuery, submitManual, clarify, applyScenario, recalculatePlan,
218	  };
219	}
